package com.schoolmanagement.guardian;
import com.schoolmanagement.school.SchoolRepository; import com.schoolmanagement.student.*; import com.schoolmanagement.security.UserContext; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/guardians") public class GuardianController { private final GuardianRepository repo;private final StudentGuardianRepository links;private final StudentRepository students;private final SchoolRepository schools;private final UserContext ctx; public GuardianController(GuardianRepository r,StudentGuardianRepository l,StudentRepository s,SchoolRepository sc,UserContext c){repo=r;links=l;students=s;schools=sc;ctx=c;} public record Request(@NotBlank String fullName,@NotBlank String phone,@Email String email){} public record LinkRequest(@NotNull Long studentId,@NotNull Long guardianId,String relationship,boolean receivesNotifications){} @GetMapping public List<Guardian> list(){return repo.findAllBySchoolId(ctx.schoolId());} @PostMapping public Guardian create(@Valid @RequestBody Request r){Guardian g=new Guardian();g.setSchool(schools.findById(ctx.schoolId()).orElseThrow());g.setFullName(r.fullName());g.setPhone(r.phone());g.setEmail(r.email());return repo.save(g);} @PostMapping("/link") public StudentGuardian link(@RequestBody LinkRequest r){Student s=students.findByIdAndSchoolId(r.studentId(),ctx.schoolId()).orElseThrow(()->new NoSuchElementException("Student not found"));Guardian g=repo.findByIdAndSchoolId(r.guardianId(),ctx.schoolId()).orElseThrow(()->new NoSuchElementException("Guardian not found"));if(links.existsByStudentIdAndGuardianId(s.getId(),g.getId()))throw new IllegalArgumentException("Guardian already linked");StudentGuardian x=new StudentGuardian();x.setStudent(s);x.setGuardian(g);x.setRelationship(r.relationship());x.setReceivesNotifications(r.receivesNotifications());return links.save(x);} }
